+                builder.startObject(name());
+                var iterator = ((List<?>) label.get()).iterator();
+                var helper = new FlattenedFieldSyntheticWriterHelper(() -> {
+                    if (iterator.hasNext()) {
+                        return (BytesRef) iterator.next();
+                    } else {
+                        return null;
+                    }
+                });
+                helper.write(builder);
+                builder.endObject();
+            }
+        }
+    }
